class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find_root(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find_root(self.parent[x])
        return self.parent[x]

    def connect(self, a, b):
        a = self.find_root(a)
        b = self.find_root(b)
        if a != b:
            if self.size[a] < self.size[b]:
                a, b = b, a
            self.parent[b] = a
            self.size[a] += self.size[b]

def power_modulo(base, exponent, modulus):
    result = 1
    while exponent > 0:
        if exponent & 1:
            result = (result * base) % modulus
        base = (base * base) % modulus
        exponent >>= 1
    return result

def main():
    n, k = map(int, input().split())
    MOD = 10**9 + 7
    if k == 0:
        print(power_modulo(n, n - 1, MOD))
        return
    uf = UnionFind(n)
    for i in range(n):
        uf.connect(i, (i * k) % n)
    total = 1
    for i in range(n):
        root = uf.find_root(i)
        if root != i:
            continue
        t = power_modulo(k, uf.size[root], n)
        if t == 1:
            total = (total * n) % MOD
    print(total)

